{"explanation":"Think of x² + 6x as an area. x² is an x-by-x square, and 6x is a strip of width 6 and length x. Cut that strip in half and put one 3-by-x piece on the right of the square and the other along the bottom. Now the shape is almost a square with side x + 3. Only the 3-by-3 corner is missing, so you have to add 9 to complete it and then take 9 away to keep the value the same: x² + 6x = (x + 3)² − 9. Use the slider to change x; the shape and the numbers update to show the identity works for every x. Check the box to show or hide the missing corner.","manimCode":"const u = 0.5;
const O = [-6, 3];
let xv = 4;
let showCorner = false;

function rectV(x0, y0, w, h) {
  return [[x0, y0, 0], [x0 + w, y0, 0], [x0 + w, y0 - h, 0], [x0, y0 - h, 0]];
}

const sq = new Polygon({ vertices: rectV(O[0], O[1], xv * u, xv * u), color: BLUE });
sq.setFill(BLUE, 0.5);
const rR = new Polygon({ vertices: rectV(O[0] + xv * u, O[1], 3 * u, xv * u), color: GREEN });
rR.setFill(GREEN, 0.5);
const rB = new Polygon({ vertices: rectV(O[0], O[1] - xv * u, xv * u, 3 * u), color: GREEN });
rB.setFill(GREEN, 0.5);
const corner = new Polygon({ vertices: rectV(O[0] + xv * u, O[1] - xv * u, 3 * u, 3 * u), color: GOLD });
corner.setFill(GOLD, 0.6);

let labels = [];
function makeLabels() {
  labels.forEach(l => scene.remove(l));
  labels = [];
  const s = xv * u, t = 3 * u;
  const mk = (str, pos, col, fs) => {
    const tx = new Text({ text: str, color: col, fontSize: fs || 26 });
    tx.moveTo(pos);
    labels.push(tx);
    scene.add(tx);
  };
  mk('x', [O[0] + s / 2, O[1] + 0.3, 0], WHITE);
  mk('3', [O[0] + s + t / 2, O[1] + 0.3, 0], WHITE);
  mk('x', [O[0] - 0.3, O[1] - s / 2, 0], WHITE);
  mk('3', [O[0] - 0.3, O[1] - s - t / 2, 0], WHITE);
  mk('x²', [O[0] + s / 2, O[1] - s / 2, 0], WHITE, 30);
  mk('3x', [O[0] + s + t / 2, O[1] - s / 2, 0], WHITE);
  mk('3x', [O[0] + s / 2, O[1] - s - t / 2, 0], WHITE);
  if (showCorner) mk('9', [O[0] + s + t / 2, O[1] - s - t / 2, 0], BLACK, 30);
  const lhs = xv * xv + 6 * xv;
  const full = (xv + 3) * (xv + 3);
  mk('x = ' + xv + ':  ' + (xv * xv) + ' + ' + (6 * xv) + ' = ' + lhs + ' = ' + full + ' − 9', [3, -2.8, 0], YELLOW, 26);
}

function update() {
  const s = xv * u, t = 3 * u;
  sq.setVertices(rectV(O[0], O[1], s, s));
  rR.setVertices(rectV(O[0] + s, O[1], t, s));
  rB.setVertices(rectV(O[0], O[1] - s, s, t));
  corner.setVertices(rectV(O[0] + s, O[1] - s, t, t));
  scene.remove(corner);
  if (showCorner) scene.add(corner);
  makeLabels();
}

// Equations
const e1 = new MathTex({ latex: 'x^2 + 6x' });
const e2 = new MathTex({ latex: '= x^2 + 3x + 3x' });
const e3 = new MathTex({ latex: '= (x^2 + 3x + 3x + 9) - 9' });
const e4 = new MathTex({ latex: '= (x+3)^2 - 9', color: GOLD });
for (const e of [e1, e2, e3, e4]) await e.waitForRender();
e1.moveTo([3, 2.6, 0]);
e2.moveTo([3, 1.6, 0]);
e3.moveTo([3, 0.6, 0]);
e4.moveTo([3, -0.6, 0]);
[e1, e2, e3, e4].forEach(e => e.scale(0.85));

await scene.play(new Write(e1));
await scene.play(new DrawBorderThenFill(sq));
await scene.play(new Write(e2));
await scene.play(new AnimationGroup([new DrawBorderThenFill(rR), new DrawBorderThenFill(rB)]));
makeLabels();
await scene.wait(0.5);
showCorner = true;
await scene.play(new FadeIn(corner));
makeLabels();
await scene.play(new Write(e3));
await scene.play(new Write(e4));

const controls = new Controls(scene, { position: 'bottom-left' });
controls.addSlider({ label: 'x', min: 1, max: 6, value: 4, step: 1, onChange: (v) => { xv = v; update(); } });
controls.addCheckbox({ label: 'Complete the square (+9)', checked: true, onChange: (c) => { showCorner = c; update(); } });

await scene.wait(999999);"}

